#!/usr/bin/env bash
# Generates the primitive variants of the versioned arrays, rings and derived values from one template each, so they all
# behave the same. Run from the repository root after changing a template; the output is committed.
set -euo pipefail
out=src/main/java/com/truesim/common/state

array() { # Name type differs(a,b) equality-doc
    local name=$1 type=$2 differs=$3 doc=$4
    cat > "$out/Versioned${name}Array.java" <<EOF
package com.truesim.common.state;

import java.util.Arrays;
import java.util.Objects;

// Generated by tools/generate-primitives.sh: change the template there, not this file.

/**
 * A fixed number of {@code ${type}} entries, each with its own change stamp, e.g. per-entity values that a HUD or a
 * render buffer mirrors: a consumer copies only the entries {@link #changesSince} visits. ${doc}
 */
public final class Versioned${name}Array implements Versioned {

    private final ChangeClock clock;
    private final ${type}[] values;
    private final long[] stamps;
    private final ChangeLog log;
    private long version;

    Versioned${name}Array(ChangeClock clock, int length, int logCapacity) {
        this.clock = clock;
        this.values = new ${type}[length];
        this.stamps = new long[length];
        this.log = new ChangeLog(logCapacity, false);
        this.version = clock.stamp();
        Arrays.fill(stamps, version);
        log.reset(version);
    }

    public int length() {
        return values.length;
    }

    public ${type} get(int index) {
        return values[index];
    }

    /** Sets entry {@code index}; returns whether that was a change. */
    public boolean set(int index, ${type} value) {
        clock.check(); // before anything changes
        ${type} old = values[Objects.checkIndex(index, values.length)];
        if (!(${differs})) {
            return false;
        }
        values[index] = value;
        stamps[index] = version = clock.stamp();
        log.addIndex(version, index);
        return true;
    }

    /** When entry {@code index} last changed. */
    public long version(int index) {
        return stamps[index];
    }

    @Override
    public long version() {
        return version;
    }

    /**
     * Visits the entries that changed after {@code since}, each once, in the order of their latest changes, and
     * returns {@code true}; or returns {@code false} without visiting when the change log no longer reaches back to
     * {@code since} (or {@code since} is from before the array existed), and the consumer should copy everything.
     */
    public boolean changesSince(long since, IndexVisitor visitor) {
        if (!log.covers(since)) {
            return false;
        }
        for (int i = log.firstAfter(since); i < log.size(); i++) {
            int index = log.index(i);
            if (stamps[index] == log.stamp(i)) {
                visitor.changed(index);
            }
        }
        return true;
    }
}
EOF
}

ring() { # Name type
    local name=$1 type=$2
    cat > "$out/Versioned${name}Ring.java" <<EOF
package com.truesim.common.state;

import java.util.Objects;

// Generated by tools/generate-primitives.sh: change the template there, not this file.

/**
 * The latest {@code ${type}} samples of a stream in a ring of fixed capacity, e.g. the values a chart streams: appending
 * beyond the capacity drops the oldest. Samples have absolute indices that count every sample appended, so a consumer
 * remembers where it got to and copies only what was appended since:
 *
 * <pre>{@code
 * long since = cursor.mark();
 * if (!samples.changesSince(since, (from, to) -> {
 *     samples.copy(from, to, buffer, 0);
 *     chart.append(buffer, (int) (to - from));
 * })) {
 *     chart.reset(samples); // first time, after clear(), or the change log overflowed
 * }
 * }</pre>
 *
 * <p>Each append, of one sample or many, is one change; {@link #clear()} is a change of structure. Appending, reading
 * and {@link #changesSince} allocate nothing.
 */
public final class Versioned${name}Ring implements Versioned {

    private final ChangeClock clock;
    private final ${type}[] values;
    private final RangeLog log;
    private long appended;
    private int size;
    private long version;
    private long structureVersion;

    Versioned${name}Ring(ChangeClock clock, int capacity, int logCapacity) {
        if (capacity < 1) {
            throw new IllegalArgumentException("A ring needs room for at least one sample: " + capacity);
        }
        this.clock = clock;
        this.values = new ${type}[capacity];
        this.log = new RangeLog(logCapacity);
        this.version = clock.stamp();
        this.structureVersion = version;
        log.reset(version);
    }

    /** The number of samples the ring holds at most. */
    public int capacity() {
        return values.length;
    }

    /** The number of samples held: at most {@link #capacity()}. */
    public int size() {
        return size;
    }

    /** The number of samples appended ever, also before a {@link #clear()}: the absolute index of the next one. */
    public long appended() {
        return appended;
    }

    /** The absolute index of the oldest sample held: {@code appended() - size()}. */
    public long first() {
        return appended - size;
    }

    /**
     * The sample with absolute index {@code index}.
     *
     * @throws IndexOutOfBoundsException if that sample is not held, from {@link #first()} to {@link #appended()}
     */
    public ${type} get(long index) {
        if (index < first() || index >= appended) {
            throw new IndexOutOfBoundsException("Sample " + index + " is not held: " + first() + " to " + appended);
        }
        return values[(int) (index % values.length)];
    }

    /**
     * The newest sample.
     *
     * @throws IndexOutOfBoundsException if the ring is empty
     */
    public ${type} latest() {
        return get(appended - 1);
    }

    /** Appends {@code value}, dropping the oldest sample if the ring is full. */
    public void append(${type} value) {
        clock.check(); // before anything changes
        values[(int) (appended % values.length)] = value;
        if (size < values.length) {
            size++;
        }
        version = clock.stamp();
        log.add(version, appended++);
    }

    /**
     * Appends {@code values[from]} to {@code values[to - 1]} as one change, dropping the oldest samples as needed; of
     * more samples than the ring holds, the last ones stay. Appending none is no change.
     */
    public void append(${type}[] values, int from, int to) {
        clock.check();
        Objects.checkFromToIndex(from, to, values.length);
        int count = to - from;
        if (count == 0) {
            return;
        }
        int capacity = this.values.length;
        int skip = count > capacity ? count - capacity : 0; // dropped right away
        int remaining = count - skip;
        int slot = (int) ((appended + skip) % capacity);
        int part = remaining < capacity - slot ? remaining : capacity - slot;
        System.arraycopy(values, from + skip, this.values, slot, part);
        System.arraycopy(values, from + skip + part, this.values, 0, remaining - part); // wrapped around
        size = count < capacity - size ? size + count : capacity;
        version = clock.stamp();
        log.add(version, appended);
        appended += count;
    }

    /**
     * Copies the samples with absolute indices {@code from} to {@code to - 1} into {@code out}, starting at
     * {@code offset}, e.g. those {@link #changesSince} visits.
     *
     * @throws IndexOutOfBoundsException if a sample is not held or {@code out} has no room for them
     */
    public void copy(long from, long to, ${type}[] out, int offset) {
        if (from < first() || to > appended || from > to) {
            throw new IndexOutOfBoundsException("Samples " + from + " to " + to + " are not held: " + first() + " to "
                + appended);
        }
        int count = (int) (to - from);
        Objects.checkFromIndexSize(offset, count, out.length);
        int slot = (int) (from % values.length);
        int part = count < values.length - slot ? count : values.length - slot;
        System.arraycopy(values, slot, out, offset, part);
        System.arraycopy(values, 0, out, offset + part, count - part); // wrapped around
    }

    /** Drops every sample; {@link #appended()} stays. Consumers rebuild afterwards. */
    public void clear() {
        clock.check();
        size = 0;
        version = structureVersion = clock.stamp();
        log.reset(version);
    }

    /** When samples were last appended or cleared. */
    @Override
    public long version() {
        return version;
    }

    /** When the ring was last cleared, or created. */
    public long structureVersion() {
        return structureVersion;
    }

    /**
     * Visits the range of absolute indices of the samples appended after {@code since} that are still held, if there
     * are any, and returns {@code true}; or returns {@code false} without visiting when that cannot be told and the
     * consumer should rebuild: the ring was cleared since, the change log overflowed, or {@code since} is from before
     * the ring existed.
     */
    public boolean changesSince(long since, RangeVisitor visitor) {
        if (!log.covers(since)) {
            return false;
        }
        long start = log.startAfter(since);
        if (start >= 0) {
            visitor.changed(start < first() ? first() : start, appended); // the oldest may be overwritten already
        }
        return true;
    }
}
EOF
}

derived() { # Name type Supplier method differs(next,value) equality-doc
    local name=$1 type=$2 supplier=$3 method=$4 differs=$5 doc=$6
    cat > "$out/Derived${name}.java" <<EOF
package com.truesim.common.state;

import com.truesim.annotations.AllowAllocation;
import java.util.Objects;
import java.util.function.${supplier};

// Generated by tools/generate-primitives.sh: change the template there, not this file.

/**
 * A {@link Derived} {@code ${type}} without boxing: recomputing allocates nothing, so it suits values derived every
 * frame. ${doc}
 */
public final class Derived${name} implements Versioned {

    private final ${supplier} compute;
    private final Versioned[] inputs;
    private ${type} value;
    private long version = -1;
    private long inputsSeen = -1;

    private Derived${name}(${supplier} compute, Versioned[] inputs) {
        this.compute = compute;
        this.inputs = inputs;
    }

    /** A value computed by {@code compute} from {@code inputs}. */
    @AllowAllocation("created once")
    public static Derived${name} of(${supplier} compute, Versioned... inputs) {
        return new Derived${name}(Objects.requireNonNull(compute, "compute"), inputs.clone());
    }

    /** The value, recomputed first if an input changed since the last computation. */
    public ${type} get() {
        refresh();
        return value;
    }

    @Override
    public long version() {
        refresh();
        return version;
    }

    private void refresh() {
        long newest = 0;
        for (Versioned input : inputs) {
            newest = Math.max(newest, input.version());
        }
        if (newest <= inputsSeen) {
            return;
        }
        ${type} next = compute.${method}();
        inputsSeen = newest;
        if (version < 0 || ${differs}) {
            value = next;
            version = newest;
        }
    }
}
EOF
}

array Double double "Double.doubleToLongBits(old) != Double.doubleToLongBits(value)" \
    "Setting the same value (bit for bit, so NaN equals NaN) is not a change."
array Float float "Float.floatToIntBits(old) != Float.floatToIntBits(value)" \
    "Setting the same value (bit for bit, so NaN equals NaN) is not a change."
array Int int "old != value" "Setting the same value is not a change."
array Long long "old != value" "Setting the same value is not a change."

ring Double double
ring Float float

derived Double double DoubleSupplier getAsDouble "Double.doubleToLongBits(next) != Double.doubleToLongBits(value)" \
    "An equal result (bit for bit) is not a change."
derived Int int IntSupplier getAsInt "next != value" "An equal result is not a change."
derived Long long LongSupplier getAsLong "next != value" "An equal result is not a change."
derived Boolean boolean BooleanSupplier getAsBoolean "next != value" "An equal result is not a change."
